script:
doc = frappe.get_doc({
    "doctype": "Fee Structure",
    "program": frappe.form_dict.class_name,
    "academic_year": frappe.form_dict.fin_yr
})
if frappe.form_dict.is_ins:
    doc.institution = frappe.form_dict.ins_name
else:
    doc.school = frappe.form_dict.ins_name
doc.append('components',{
    'fees_category': frappe.form_dict.fee_type,
    'amount': frappe.form_dict.amount
})
doc.insert()
